export const ecosystemSignalsByHarness = new Map<string, EcosystemSignalSnapshot[]>();
for (const signal of ecosystemSignalSnapshots) {
  const existing = ecosystemSignalsByHarness.get(signal.harnessId) ?? [];
  existing.push(signal);
  ecosystemSignalsByHarness.set(signal.harnessId, existing);
}
